    maxRecords: integer(value.maxRecords, 'GRPC_STREAM_RECORDS_INVALID', 100000, 1, 1000000),
    idleTimeoutMs: integer(value.idleTimeoutMs, 'GRPC_STREAM_IDLE_TIMEOUT_INVALID', 10000, 1, 300000),
