// MIT. Public, offline merchant plan; original SF61 generates SF30 offers/service.
import { lstat, readFile } from 'node:fs/promises';
import { importOpenApi } from '../../sf61-openapi-seller-import/importer.mjs';
import { createSellerServiceConfig } from '../../sf61-openapi-seller-import/service-config.mjs';
import { compileUpstreamBindings, upstreamCredentialReferences } from '../upstream.mjs';
import { compileAvailabilityPolicy } from '../upstream-readiness.mjs';
import { METHODS, LIMITS, NETWORKS, requestSchema, exampleRequest,
  responseSchema } from './stellar.mjs';

export const PLAN_SCHEMA = 'stellar-forge.stellar-jsonrpc-merchant.v1';
export { METHODS, LIMITS, NETWORKS };
export const plain = value => value !== null && typeof value === 'object' && !Array.isArray(value) &&
  [Object.prototype, null].includes(Object.getPrototypeOf(value));
const fail = message => { throw new TypeError(message); };
const envName = name => typeof name === 'string' && /^[A-Za-z_][A-Za-z0-9_]{0,79}$/.test(name);
function fields(value, names, label) {
  if (!plain(value) || Object.keys(value).some(key => !names.includes(key))) fail('Invalid ' + label + ' fields');
}
function integer(value, min, max, name) {
  if (!Number.isSafeInteger(value) || value < min || value > max) fail('Invalid ' + name);
}
export async function readPlan(path) {
  const info = await lstat(path);
  if (!info.isFile() || info.size > 131072) fail('Plan must be a regular JSON file up to 128 KiB');
  const data = await readFile(path);
  if (data.length > 131072) fail('Plan exceeds 128 KiB');
  return validatePlan(JSON.parse(new TextDecoder('utf-8', { fatal: true }).decode(data)));
}

export function validatePlan(input) {
  fields(input, ['schema', 'publicOrigin', 'dataNetwork', 'endpointEnv', 'headerEnv',
    'oauth2', 'payment', 'operations', 'limits', 'upstreamAvailability'], 'RPC plan');
  if (input.schema !== PLAN_SCHEMA) fail('Expected ' + PLAN_SCHEMA);
  if (!Object.hasOwn(NETWORKS, input.dataNetwork)) fail('Select stellar:pubnet or stellar:testnet data');
  if (!envName(input.endpointEnv)) fail('endpointEnv must name a private environment variable');
  let origin;
  try { origin = new URL(input.publicOrigin); } catch { fail('Canonical public merchant HTTPS origin required'); }
  if (origin.protocol !== 'https:' || input.publicOrigin !== origin.origin || origin.username || origin.password)
    fail('Canonical public merchant HTTPS origin required');
  fields(input.payment, ['network', 'asset', 'payTo', 'maxTimeoutSeconds'], 'payment');
  const limits = { ...LIMITS, ...(input.limits ?? {}) };
  if (input.limits !== undefined) fields(input.limits, Object.keys(LIMITS), 'limits');
  for (const [name, min, max] of [['timeoutMs', 1000, 60000], ['maxResponseBytes', 1024, 1048576],
    ['maxInFlight', 1, 64], ['maxEventPage', 1, 10000], ['maxTransactionPage', 1, 200],
    ['maxLedgerKeys', 1, 200], ['maxLedgerPage', 1, 200]]) integer(limits[name], min, max, name);
  if (!Array.isArray(input.operations) || input.operations.length < 1 || input.operations.length > METHODS.length)
    fail('Choose explicit Stellar read products with atomic prices');
  const selected = new Set();
  const operations = input.operations.map(row => {
    fields(row, ['method', 'amountAtomic'], 'operation');
    if (!METHODS.includes(row.method) || selected.has(row.method)) fail('Unknown or duplicate Stellar read method');
    selected.add(row.method);
    if (typeof row.amountAtomic !== 'string' || !/^[1-9][0-9]{0,38}$/.test(row.amountAtomic))
      fail('Set a positive atomic-unit price for every selected product');
    return { method: row.method, amountAtomic: row.amountAtomic };
  });
  const auth = {
    ...(input.headerEnv === undefined ? {} : { headerEnv: structuredClone(input.headerEnv) }),
    ...(input.oauth2 === undefined ? {} : { oauth2: structuredClone(input.oauth2) }),
  };
  // Exercise ORIGINAL declaration validation with local placeholder values only.
  // This never reads process.env or constructs a provider or network request.
  const declaration = { schema: 'stellar-forge.seller-upstreams.v1', bindings: {
    declaration: { origin: 'https://rpc.example', path: '/rpc', method: 'POST', ...auth },
  } };
  const references = upstreamCredentialReferences(declaration);
  if (references.some(name => !envName(name))) fail('Invalid credential environment reference');
  compileUpstreamBindings(declaration, { env: Object.fromEntries(references.map(name => [name, 'offline-declaration-value'])) });
  const upstreamAvailability = input.upstreamAvailability === undefined ? undefined :
    compileAvailabilityPolicy(input.upstreamAvailability);
  return { schema: PLAN_SCHEMA, publicOrigin: origin.origin, dataNetwork: input.dataNetwork,
    endpointEnv: input.endpointEnv, ...auth, payment: structuredClone(input.payment),
    operations, limits, ...(upstreamAvailability === undefined ? {} : { upstreamAvailability }) };
}

export function credentialReferences(plan) {
  const references = upstreamCredentialReferences({ schema: 'stellar-forge.seller-upstreams.v1',
    bindings: { rpc: { ...(plan.headerEnv ? { headerEnv: plan.headerEnv } : {}),
      ...(plan.oauth2 ? { oauth2: plan.oauth2 } : {}) } } });
  return [...new Set([plan.endpointEnv, ...references])].sort();
}

export function prepareProduct(input) {
  const plan = validatePlan(input);
  const spec = { openapi: '3.1.0', info: { title: 'Stellar RPC read merchant', version: '1.0.0',
    description: 'Selected Stellar reads on ' + plan.dataNetwork + '. Payment network is declared separately in each original offer.' },
    servers: [{ url: plan.publicOrigin + '/' }], paths: {} };
  const selections = [], bindings = [];
  for (const { method, amountAtomic } of plan.operations) {
    const path = '/stellar/' + method;
    spec.paths[path] = { post: { operationId: method, summary: method + ' on ' + plan.dataNetwork,
      description: 'One fixed ' + method + ' read. Send the params object only. The response preserves the original JSON-RPC success envelope bytes. Every page is a separate purchase.',
      requestBody: { required: true, content: { 'application/json': {
        schema: requestSchema(method, plan.limits), example: exampleRequest(method),
      } } }, responses: {
        '200': { description: 'Original JSON-RPC result envelope. FAILED and NOT_FOUND transaction statuses describe chain data.',
          content: { 'application/json': { schema: responseSchema(method, plan.limits, plan.dataNetwork) } } },
        '422': { description: 'Request parameters rejected before payment.' },
        '502': { description: 'Provider HTTP, JSON-RPC or result contract failed.' },
        '503': { description: 'Product paused, merchant draining, or provider admission unavailable.' },
      } } };
    selections.push({ method: 'POST', path, serviceName: 'Stellar ' + method,
      accepts: [{ scheme: 'exact', ...plan.payment, amount: amountAtomic }] });
    bindings.push({ method: 'POST', path, id: method, handler: method,
      admit: 'admit' + method, validateInput: true });
  }
  const imported = importOpenApi(spec, selections);
  const service = createSellerServiceConfig(imported, bindings);
  return { plan, spec, selections, bindings, imported, service };
}

// MIT. Provider-neutral Stellar read contracts; reuse the original PR1003 inputs.
import { METHODS as existingMethods, LIMITS as existingLimits, plain,
  requestSchema as existingSchema, exampleRequest as existingExample,
  admitRequest as existingAdmission, rpcParams as existingParams,
} from '../../partners/getblock-stellar/product.mjs';

export const METHODS = Object.freeze(['getEvents', 'getFeeStats', 'getHealth',
  'getLatestLedger', 'getLedgerEntries', 'getLedgers', 'getNetwork',
  'getTransaction', 'getTransactions', 'getVersionInfo']);
export const LIMITS = Object.freeze({ ...existingLimits, maxLedgerPage: 200 });
export const NETWORKS = Object.freeze({
  'stellar:pubnet': 'Public Global Stellar Network ; September 2015',
  'stellar:testnet': 'Test SDF Network ; September 2015',
});
const emptyMethods = new Set(['getFeeStats', 'getHealth', 'getLatestLedger', 'getNetwork', 'getVersionInfo']);
const ledger = { type: 'integer', minimum: 1, maximum: 4294967295 };
const integer = { type: 'integer', minimum: 0, maximum: 4294967295 };
const text = (maxLength, minLength = 0) => ({ type: 'string', minLength, maxLength });
const obj = (properties, required = [], additionalProperties = true) =>
  ({ type: 'object', properties, required, additionalProperties });
const list = maxItems => ({ type: 'array', maxItems, items: { type: 'object' } });
const ledgerLimits = limits => ({ ...limits, maxTransactionPage: limits.maxLedgerPage });
const supported = method => {
  if (!METHODS.includes(method)) throw new TypeError('Select a supported Stellar RPC read');
};

export function requestSchema(method, limits = LIMITS) {
  supported(method);
  if (existingMethods.includes(method)) return existingSchema(method, limits);
  // Stellar getLedgers uses the same startLedger/cursor/base64 input contract.
  if (method === 'getLedgers') return existingSchema('getTransactions', ledgerLimits(limits));
  return obj({}, [], false);
}
export function exampleRequest(method) {
  supported(method);
  return emptyMethods.has(method) ? {} : existingExample(method);
}
export function admitRequest(method, context, limits = LIMITS) {
  supported(method);
  if (existingMethods.includes(method)) return existingAdmission(method, context, limits);
  if (method === 'getLedgers') return existingAdmission('getTransactions', context, ledgerLimits(limits));
  return context?.method === 'POST' && plain(context.body) &&
    Object.keys(context.body).length === 0 && !context.url?.search &&
    Object.keys(context.query ?? {}).length === 0 ? true : {
      status: 422, headers: { 'content-type': 'application/json' },
      body: { error: 'STELLAR_READ_INPUT_INVALID', field: 'request' },
    };
}
export function rpcParams(method, body, limits = LIMITS) {
  supported(method);
  if (existingMethods.includes(method)) return existingParams(method, body, limits);
  if (method === 'getLedgers') return existingParams('getTransactions', body, ledgerLimits(limits));
  return undefined; // Methods with zero parameters omit params on the RPC wire.
}

/** Required stable fields, with future result fields preserved in original bytes. */
export function resultSchema(method, limits = LIMITS, network) {
  supported(method);
  if (method === 'getNetwork') return obj({
    passphrase: network ? { const: NETWORKS[network] } : text(256, 1),
    protocolVersion: integer, friendbotUrl: text(2048),
  }, ['passphrase', 'protocolVersion']);
  if (method === 'getHealth') return obj({ status: { const: 'healthy' },
    latestLedger: ledger, oldestLedger: ledger, ledgerRetentionWindow: ledger,
    latestLedgerCloseTime: text(24), oldestLedgerCloseTime: text(24),
  }, ['status', 'latestLedger', 'oldestLedger', 'ledgerRetentionWindow']);
  if (method === 'getLatestLedger') return obj({ id: text(64, 64),
    protocolVersion: integer, sequence: ledger, closeTime: text(24),
  }, ['id', 'protocolVersion', 'sequence']);
  if (method === 'getFeeStats') return obj({ latestLedger: ledger,
    inclusionFee: { type: 'object' }, sorobanInclusionFee: { type: 'object' },
  }, ['latestLedger', 'inclusionFee', 'sorobanInclusionFee']);
  if (method === 'getVersionInfo') return obj({ version: text(256, 1),
    commitHash: text(128), buildTimestamp: text(128),
    captiveCoreVersion: text(512), protocolVersion: integer,
  }, ['version']);
  if (method === 'getTransaction') return obj({ latestLedger: ledger,
    status: { enum: ['SUCCESS', 'FAILED', 'NOT_FOUND'] }, txHash: text(64, 64),
  }, ['latestLedger', 'status', 'txHash']);
  const key = { getEvents: 'events', getTransactions: 'transactions',
    getLedgers: 'ledgers', getLedgerEntries: 'entries' }[method];
  const maximum = { getEvents: limits.maxEventPage,
    getTransactions: limits.maxTransactionPage, getLedgers: limits.maxLedgerPage,
    getLedgerEntries: limits.maxLedgerKeys }[method];
  const properties = { latestLedger: ledger, [key]: list(maximum) };
  const required = ['latestLedger', key];
  if (method !== 'getLedgerEntries') {
    properties.cursor = text(512); required.push('cursor');
  }
  return obj(properties, required);
}

export const correlationId = method => 'sf30:' + method;
export function responseSchema(method, limits = LIMITS, network) {
  return obj({ jsonrpc: { const: '2.0' }, id: { const: correlationId(method) },
    result: resultSchema(method, limits, network), error: false,
  }, ['jsonrpc', 'id', 'result']);
}
export function responseContract(method, limits = LIMITS, network) {
  return { schema: 'stellar-forge.upstream-response-contract.v1', method: 'POST',
    responses: { '200': { content: { 'application/json': responseSchema(method, limits, network) } } } };
}

/** Associations not expressible in a static response contract. No data rewriting. */
export function resultMatchesRequest(method, result, params = {}) {
  if (method === 'getTransaction' && result.txHash !== params.hash) return false;
  if (method === 'getHealth' && result.oldestLedger > result.latestLedger) return false;
  if (method === 'getLatestLedger' && !/^[a-f0-9]{64}$/.test(result.id)) return false;
  const key = { getEvents: 'events', getTransactions: 'transactions',
    getLedgers: 'ledgers', getLedgerEntries: 'entries' }[method];
  if (!key) return true;
  const rows = result[key];
  if (method === 'getLedgerEntries') {
    const requested = new Set(params.keys), found = new Set();
    return rows.every(row => typeof row.key === 'string' && requested.has(row.key) &&
      !found.has(row.key) && (found.add(row.key), true));
  }
  if (rows.length > params.pagination.limit) return false;
  return rows.every(row => {
    const sequence = method === 'getLedgers' ? row.sequence : row.ledger;
    return Number.isSafeInteger(sequence) && sequence > 0 && sequence <= result.latestLedger &&
      (params.startLedger === undefined || sequence >= params.startLedger) &&
      (params.endLedger === undefined || sequence < params.endLedger);
  });
}

# Kafka workspace Node client

Use the same running Kafka Application from Node, a command line, or the merchant MCP host. This client covers the complete retained workflow: connection revisions, real topic inspections, exact offset capture and recovery, source projections, native dataset plans/builds/queries/comparisons, portable receiving, and merchant-package export.

The entry point is [client.mjs](client.mjs), with the complete TypeScript contract in [client.d.mts](client.d.mts). [client-cli.mjs](client-cli.mjs) exposes the same operations as commands. [client-protocol.mjs](client-protocol.mjs) contains the original connection, numeric, identity, and HTTP limits.

The client uses Node built-ins and the maintained Node 22.16-or-newer runtime. Its exact JSON path checks for the runtime's standard JSON source-text access and raw numeric serialization before parsing a response. The native Kafka Application retains its original Python/confluent-kafka dependencies and its original 26-file workspace binding. These additional consumer modules do not alter that binding.

## Connect to the original Application

Open the existing `dataset-kafka` Application and select its private connection file. The reader accepts either the original printed URL, with an optional terminal newline, or the original `stellar-forge.application-url.v1` record for `dataset-kafka`. A directly operated original server can publish the same file:

~~~sh
node kafka/cli.mjs --workspace /private/customer/kafka serve \
  --connection-file /private/customer/kafka.connection \
  --startup-format json
~~~

The directory and initialized workspace in that command are the operator's existing selections. Applications owns its managed launch, stop, and reopen lifecycle. A client command borrows the running server.

~~~js
import { KafkaWorkspaceClient } from './kafka/client.mjs';

const client = new KafkaWorkspaceClient({
  connectionFile: '/private/customer/kafka.connection',
  // Optional host-selected expectedWorkspaceId and expectedBindingSha256
});
try {
  const current = await client.inspect();
  console.log(current.workspaceId, current.bindingSha256);
  const state = await client.state();
  console.log(state.kafka.connections);
} finally {
  await client.close();
}
~~~

`readKafkaWorkspaceConnection(filename)` is the shared connection reader for host integrations. It opens a regular private operator-owned file without following a final symlink, checks its complete bytes and file identity across the read, and accepts only the exact original loopback URL with its 43-character capability. The returned object is frozen. Its private `token` and `consoleUrl` properties are non-enumerable; the Applications metadata view contains only the original launch identity fields.

Every client operation rereads that original file, authenticates `GET /api/launch`, and binds the live workspace UUID, absolute workspace, and original source-binding SHA. A managed restart may publish a new port and token for the same binding. A different workspace or source binding requires an explicit new client selection. `inspect()` reports the live origin and identity with the private capability removed.

HTTP goes directly to `127.0.0.1` through `node:http`. It uses the original Host, Origin, and Bearer fields, exact Content-Length, identity encoding, and the original fixed route table. Redirects and environment proxy routing do not participate. The client keeps at most four native requests active, leaving capacity in the original eight-slot server for its browser.

## Complete source-to-dataset operation

The following illustrates a caller using an already saved exact-topic connection. Operation names are retained identities: reuse the same names and request bytes when recovering an interrupted operation.

~~~js
const connection = await client.connection('customer-events');
const inspected = await client.inspectConnection({
  connection: connection.id,
  revision: connection.revision,
  operation: 'customer-events-inspection-01'
});

// Select the customer's intended intervals from the actual committed bounds.
// Kafka offsets remain decimal strings from the original inspection.
const capture = await client.prepareCapture({
  inspection: inspected.id,
  operation: 'customer-events-capture-01',
  ranges: inspected.partitions.map(part => ({
    partition: part.partition,
    start: part.low,
    end: part.end
  }))
});
await client.runCapture({capture: capture.id, expectedRevision: capture.revision});
const completed = await client.waitForCapture(capture.id);
if (completed.status !== 'COMPLETE') {
  throw new Error('Review the retained capture state: ' + completed.status);
}

const projection = await client.project({
  operation: 'customer-events-edition-01',
  captures: [{id: completed.id, revision: completed.revision}],
  view: 'events',
  decode: 'json',
  deletePolicy: 'retain',
  acceptIncomplete: false,
  label: 'Customer event edition'
});
const plan = await client.savePlan(projection.defaultPlan);
const build = await client.build({source: projection.source, plan: plan.id});
const queried = await client.query({
  build: build.id,
  query: {limit: '25', offset: '0'}
});
const delivery = await client.exportKafka(
  {build: build.id, projection: projection.id},
  '/private/customer/deliveries/customer-events.zip'
);
console.log(queried, delivery.sha256);
~~~

The original inspection records the actual cluster identity, topic UUID, each retained low offset, read-uncommitted high watermark, and read-committed end. The client preserves all of those fields. `configuredTopics()` lists the exact topics already saved in workspace connections; `inspectConnection()` performs the explicitly selected original broker/topic operation.

The original capture engine owns committed-record visibility, partition completion evidence, retention/source-change detection, byte limits, cancellation, and resumable revisions. `runCapture()` and `resumeCapture()` invoke the same native route. They retain the original capture, connection revision, cluster/topic binding, and operation identity.

Projection parameters keep the native choices explicit. `events` preserves the selected event history. `latest-per-partition-key` uses the original partition/key semantics. Decoding is `json` or `bytes`; deletion is `retain`, `tombstone`, or `tombstone-or-goldsky`. `acceptIncomplete` is an explicit source-coverage decision enforced by the native workspace.

## Exact message and JSON values

`messages(capture, {offset, limit})` returns the original compact message summaries: original IDs, partition/offset/timestamp identity, payload sizes, key preview, ordered-header count, native value state, and deletion metadata. It pages 1–200 summaries at a time.

`message(id)` returns the complete original retained detail, including base64 key/value bytes, ordered headers, decoded value, parse status, and `valueJson`. The native timestamp and Kafka offsets are decimal strings. `valueJson` preserves the native numeric tokens; code that needs a decoded object should use `parseKafkaJson`.

~~~js
import {
  KafkaJsonNumber, parseKafkaJson, stringifyKafkaJson
} from './kafka/client.mjs';

const value = parseKafkaJson(
  '{"offset":"9007199254740993","amount":1.2300,"eventId":9007199254740993}'
);

console.log(value.offset);           // original string
console.log(value.amount.source);    // "1.2300"
console.log(value.eventId.source);   // "9007199254740993"

// Native JSON output preserves the original numeric tokens.
console.log(stringifyKafkaJson(value));

// Ordinary JSON transport uses an explicit exact-number tag.
console.log(JSON.stringify(value));
// {"offset":"9007199254740993","amount":{"$kafkaNumber":"1.2300"},
//  "eventId":{"$kafkaNumber":"9007199254740993"}}

const selected = new KafkaJsonNumber('9.007199254740993e15');
~~~

Safe, canonical integer metadata remains a JavaScript number. Other original numeric lexemes become immutable `KafkaJsonNumber` values. Their `source` property is exact; implicit numeric conversion throws. Ordinary `JSON.stringify` emits `{"$kafkaNumber":"original token"}` for MCP or other JSON transports. `stringifyKafkaJson` is the explicit serializer for native raw-number JSON. A naturally occurring JSON object with a `$kafkaNumber` field remains an ordinary object; the parser creates number wrappers from numeric source tokens only.

Large complete messages, state, projections, records, and query responses have streamed file forms. This lets the existing retained-download/chunk reader deliver the original bytes without inlining a large response through an MCP JSON budget.

## API map

All methods return the unchanged original native result unless the table identifies a client inspection or completed file result. The full request/result shapes are in `client.d.mts`.

| Task | Client method | Original HTTP operation |
| --- | --- | --- |
| Authenticate original launch | `inspect(options?)` | `GET /api/launch` |
| Whole retained state | `state(options?)` | `GET /api/state` |
| Saved exact-topic summaries | `configuredTopics(options?)` | Derives from original state |
| Latest saved connection | `connection(name, options?)` | `GET /api/kafka/connection?id=...` |
| Save connection revision | `saveConnection({connection, expectedRevision, operation, config}, options?)` | `POST /api/kafka/connection` |
| Real topic metadata/bounds | `inspectConnection({connection, revision, operation}, options?)` | `POST /api/kafka/inspect` |
| Retained inspection | `inspection(id, options?)` | `GET /api/kafka/inspection` |
| Prepare exact ranges | `prepareCapture({inspection, operation, ranges}, options?)` | `POST /api/kafka/capture` |
| Capture state | `capture(id, options?)` | `GET /api/kafka/capture` |
| Start/resume original capture | `runCapture({capture, expectedRevision}, options?)` / `resumeCapture(...)` | `POST /api/kafka/run` |
| Cancel original capture | `cancelCapture(id, options?)` | `POST /api/kafka/cancel` |
| Wait for capture transition | `waitForCapture(id, {signal?, timeoutMs?, pollMs?})` | Reads the original capture |
| Compact message page | `messages(capture, {offset?, limit?}, options?)` | `GET /api/kafka/messages` |
| Complete message detail | `message(id, options?)` | `GET /api/kafka/message` |
