    return this.#upload('/api/source',filename,KAFKA_LIMITS.sourceBytes,
      {'Content-Type':'application/x-ndjson','X-NDJSON-Name':encodeURIComponent(name),'X-NDJSON-Label':encodeURIComponent(label)},options);
  }
  #download(route,body,filename,kind,expectedMedia,options={}) {
    const destination=hostPath(filename), parent=dirname(destination);
    const bytes=body===undefined?undefined:jsonPayload(body,KAFKA_LIMITS.datasetRequestBytes);
    const maximum=integer(options.maximumBytes??KAFKA_LIMITS.downloadBytes,1,4*1024*1024*1024,'Maximum download bytes');
    return this.#operation(async(connection,launch,signal)=>{
      const directory=await privateDirectory(parent);
      let temporary,handle,owned,published=false,retained,primary;
      try {
        try {await lstat(destination);throw failure('KAFKA_DESTINATION_EXISTS','Preserve the existing receiving file; inspect it or choose a new destination.');}
        catch(error){if(error.code!=='ENOENT')throw error;}
        temporary=parent+'/.kafka-download-'+randomUUID()+'.pending';
        handle=await open(temporary,'wx',0o600);
        owned=await handle.stat({bigint:true});
        const method=body===undefined?'GET':'POST';
        return await this.#exchange(connection,method,route,
          {body:bytes,headers:body===undefined?{}:{'Content-Type':'application/json; charset=utf-8'}},
          async response=>{
            const contentType=mediaType(response,expectedMedia), length=responseLength(response,maximum);
            const checksum=createHash('sha256');let size=0;
            for await(const chunk of response) {
              aborted(signal);size+=chunk.length;
              if(size>length||size>maximum)throw failure('KAFKA_RESPONSE_TOO_LARGE','The complete download exceeds its original declared length.');
              await handle.writeFile(chunk);checksum.update(chunk);
            }
            if(size!==length||!response.complete)
              throw failure('KAFKA_RESPONSE_INCOMPLETE','The retained download ended before its complete original bytes.');
            await handle.sync();
            const written=await handle.stat({bigint:true});
            if(written.dev!==owned.dev||written.ino!==owned.ino||written.size!==BigInt(size))
              throw failure('KAFKA_DOWNLOAD_CHANGED','The private download file changed while being written.');
            await handle.close();handle=null;
            const currentParent=await lstat(parent,{bigint:true});
            if(currentParent.dev!==directory.info.dev||currentParent.ino!==directory.info.ino)
              throw failure('KAFKA_DESTINATION_INVALID','The selected receiving directory changed.');
            retained={schema:'stellar-forge.kafka-client-download.v1',kind,path:destination,
              bytes:size,sha256:checksum.digest('hex'),contentType,
              workspaceId:launch.workspaceId,bindingSha256:launch.bindingSha256,
              request:{method,route,...(bytes?{bodySha256:hash(bytes)}:{})}};
            if(options.sha256!==undefined&&retained.sha256!==identifier(options.sha256,'Expected download SHA-256'))
              throw failure('KAFKA_DOWNLOAD_CHANGED','The original complete download differs from its selected SHA-256.');
            aborted(signal);
            await link(temporary,destination);published=true;
            await directory.handle.sync();
            return retained;
          },signal);
      } catch(error) {
        primary=error instanceof KafkaWorkspaceError?error:
          failure('KAFKA_DOWNLOAD_FAILED',error.code==='EEXIST'?'The receiving path now belongs to another completed file.':
            'The complete download could not be published in its selected private directory.');
        if(published&&retained)primary.retainedFile=retained;
        throw primary;
      } finally {
        let cleanup;
        if(handle)try{await handle.close();}catch(error){cleanup=error;}
        if(temporary)try{await removeOwned(temporary,owned);}catch(error){cleanup??=error;}
        try{await directory.handle.close();}catch(error){cleanup??=error;}
        if(cleanup&&!primary)throw failure('KAFKA_DOWNLOAD_CLEANUP','The transfer finished but its local file cleanup needs recovery.',
          published&&retained?{retainedFile:retained}:{});
      }
    },options);
  }
  exportKafka(request,destination,options={}) {
    exact(request,['build'],['projection']);identifier(request.build,'Build');
    if(request.projection!==undefined)identifier(request.projection,'Projection');
    return this.#download(requestPath('/api/kafka/export',request),undefined,destination,'kafka-project','application/zip',options);
  }
  exportNative(build,destination,options={}) {return this.#download(requestPath('/api/export',{build:identifier(build,'Build')}),undefined,destination,'ndjson-project','application/zip',options);}
  exportDataset(build,destination,options={}) {return this.#download(requestPath('/api/dataset-export',{build:identifier(build,'Build')}),undefined,destination,'dataset','application/zip',options);}
  exportChanges(id,destination,options={}) {return this.#download(requestPath('/api/changes/download',{id:identifier(id,'Comparison')}),undefined,destination,'comparison-changes','application/x-ndjson',options);}
  exportMerchant(request,destination,options={}) {
    exact(request,['build','payment','origin','path']);identifier(request.build,'Build');
    if(!plain(request.payment)||typeof request.origin!=='string'||typeof request.path!=='string')
      throw failure('KAFKA_INVALID_PARAMS','Supply the original merchant payment terms, public origin and route.');
    return this.#download('/api/merchant',request,destination,'merchant','application/zip',options);
  }
  downloadRecord(kind,id,destination,options={}) {
    const routes={connection:'/api/kafka/connection',inspection:'/api/kafka/inspection',
      capture:'/api/kafka/capture',source:'/api/source',plan:'/api/plan'};
    if(!Object.hasOwn(routes,kind))throw failure('KAFKA_INVALID_PARAMS','Select an original connection, inspection, capture, source or plan record.');
    if(kind==='connection')operationName(id,'Connection');else identifier(id,'Record');
    return this.#download(requestPath(routes[kind],{id}),undefined,destination,'record','application/json',options);
  }
  downloadQuery(request,destination,options={}) {
    exact(request,['build','query']);identifier(request.build,'Build');
    if(!plain(request.query)||Object.values(request.query).some(value=>typeof value!=='string'))
      throw failure('KAFKA_INVALID_PARAMS','Native dataset query parameters must remain scalar strings.');
    return this.#download('/api/query',request,destination,'query','application/json',options);
  }
  downloadMessage(id,destination,options={}) {return this.#download(requestPath('/api/kafka/message',{id:identifier(id,'Message')}),undefined,destination,'message','application/json',options);}
  downloadState(destination,options={}) {return this.#download('/api/state',undefined,destination,'state','application/json',options);}
  downloadProjection(id,destination,options={}) {return this.#download(requestPath('/api/kafka/projection',{id:identifier(id,'Projection')}),undefined,destination,'projection','application/json',options);}
  close() {
    if(this.#closing)return this.#closing;
    this.#closed=true;this.#controller.abort();
    this.#closing=(async()=>{
      while(this.#pending.size)await Promise.allSettled([...this.#pending]);
    })();
    return this.#closing;
  }
  async [Symbol.asyncDispose]() {await this.close();}
}

"""MIT. Exact Kafka configuration, source identity and lossless event projection."""
from __future__ import annotations
import base64
import binascii
from datetime import datetime, timezone
import hashlib
import json
import re

from shared import InputError, json_bytes, ndjson_source

MAX_SOURCE = 256 * 1024 * 1024
HEX = re.compile(r"[0-9a-f]{64}\Z")
OPERATION = re.compile(r"[A-Za-z0-9][A-Za-z0-9._:-]{0,127}\Z")
ENV = re.compile(r"[A-Za-z_][A-Za-z0-9_]{0,127}\Z")
OFFSET = re.compile(r"(0|[1-9][0-9]{0,18})\Z")
BROKER = re.compile(r"(?:[A-Za-z0-9][A-Za-z0-9.-]*|\[[0-9A-Fa-f:]+\]):[0-9]{1,5}\Z")
ACTIVE = {"RUNNING", "CANCELLING"}
STATUS = {"PREPARED", "RUNNING", "CANCELLING", "CANCELLED", "INTERRUPTED",
          "COMPLETE", "LIMIT_REACHED", "SOURCE_GAP", "SOURCE_CHANGED", "SOURCE_CONFLICT", "ERROR"}
WIRE_KEYS = {"schema", "clusterId", "topicId", "topic", "partition", "offset",
             "timestampType", "timestampMs", "leaderEpoch", "keyBase64", "valueBase64", "headers"}


def now():
    return datetime.now(timezone.utc).isoformat(timespec="milliseconds").replace("+00:00", "Z")


def digest(data):
    return hashlib.sha256(data).hexdigest()


def ident(value):
    if not isinstance(value, str) or not HEX.fullmatch(value):
        raise InputError("Choose a complete retained Kafka identifier")
    return value


def operation(value):
    if not isinstance(value, str) or not OPERATION.fullmatch(value):
        raise InputError("Operation and connection names require 1–128 letters, digits, periods, colons, dashes or underscores")
    return value


def exact(value, required, optional=()):
    if not isinstance(value, dict) or not set(required) <= set(value) or set(value) - set(required) - set(optional):
        raise InputError("Expected exactly these fields: " + ", ".join(sorted(required)))
    return value


def integer(value, low, high, label):
    if type(value) is not int or not low <= value <= high:
        raise InputError(f"{label} must be an integer from {low} to {high}")
    return value


def offset(value):
    if not isinstance(value, str) or not OFFSET.fullmatch(value) or int(value) > 9223372036854775807:
        raise InputError("Kafka offsets must be exact nonnegative signed-64-bit decimal strings")
    return value


def label(value, maximum=160):
    if not isinstance(value, str) or not value.strip() or len(value) > maximum or any(ord(c) < 32 for c in value):
        raise InputError("Choose a short printable label")
    return value


def config(raw):
    exact(raw, {"schema", "label", "brokers", "topic", "security", "requestTimeoutSeconds",
                "maxMessageBytes", "maxCaptureBytes", "maxCaptureRecords"})
    if raw["schema"] != "stellar-forge.kafka-connection.v1":
        raise InputError("Choose the original Kafka connection schema")
    label(raw["label"])
    brokers = raw["brokers"]
    if not isinstance(brokers, list) or not 1 <= len(brokers) <= 32 or any(not isinstance(item, str) for item in brokers) or len(set(brokers)) != len(brokers):
        raise InputError("Supply 1–32 unique Kafka host:port brokers")
    for broker in brokers:
        if not isinstance(broker, str) or len(broker) > 300 or not BROKER.fullmatch(broker) or not 1 <= int(broker.rsplit(":", 1)[1]) <= 65535:
            raise InputError("Kafka brokers must be explicit host:port or [IPv6]:port addresses")
    topic = raw["topic"]
    if not isinstance(topic, str) or not re.fullmatch(r"[A-Za-z0-9._-]{1,249}", topic) or topic in {".", ".."}:
        raise InputError("Choose one exact Kafka topic name")
    security = raw["security"]
    exact(security, {"protocol"}, {"mechanism", "usernameEnv", "passwordEnv", "caFileEnv",
                                  "certificateFileEnv", "keyFileEnv", "keyPasswordEnv"})
    protocol = security["protocol"]
    if protocol not in {"PLAINTEXT", "SSL", "SASL_PLAINTEXT", "SASL_SSL"}:
        raise InputError("Choose PLAINTEXT, SSL, SASL_PLAINTEXT or SASL_SSL")
    sasl = {"mechanism", "usernameEnv", "passwordEnv"}
    tls = {"caFileEnv", "certificateFileEnv", "keyFileEnv", "keyPasswordEnv"}
    if protocol.startswith("SASL"):
        if not sasl <= set(security) or security["mechanism"] not in {"PLAIN", "SCRAM-SHA-256", "SCRAM-SHA-512"}:
            raise InputError("SASL requires its mechanism and private username/password environment references")
    elif set(security) & sasl:
        raise InputError("Choose a SASL protocol before supplying SASL references")
    if not protocol.endswith("SSL") and set(security) & tls:
        raise InputError("Choose TLS before supplying certificate references")
    if bool(security.get("certificateFileEnv")) != bool(security.get("keyFileEnv")):
        raise InputError("A client certificate and private key must be selected together")
    if "keyPasswordEnv" in security and "keyFileEnv" not in security:
        raise InputError("A key password reference requires the selected private key")
    for key, value in security.items():
        if key.endswith("Env") and (not isinstance(value, str) or not ENV.fullmatch(value)):
            raise InputError("Credential references must be environment-variable names, never credential values")
    integer(raw["requestTimeoutSeconds"], 1, 120, "Request timeout")
    integer(raw["maxMessageBytes"], 1, 16 * 1024 * 1024, "Message byte limit")
    integer(raw["maxCaptureBytes"], 1, MAX_SOURCE, "Capture byte limit")
    integer(raw["maxCaptureRecords"], 1, 1000000, "Capture record limit")
    return json.loads(json_bytes(raw))


def b64(value):
    return None if value is None else base64.b64encode(value).decode("ascii")


def unb64(value):
    if value is None:
        return None
    if not isinstance(value, str):
        raise InputError("Kafka wire bytes require canonical base64 or null")
    try:
        raw = base64.b64decode(value, validate=True)
    except (ValueError, binascii.Error) as error:
        raise InputError("Invalid Kafka wire base64") from error
    if b64(raw) != value:
        raise InputError("Kafka wire base64 must be canonical")
    return raw


def wire_identity(value):
    return digest(json_bytes({key: value[key] for key in ("clusterId", "topicId", "partition", "offset")}))


def wire(raw):
    exact(raw, WIRE_KEYS)
    if raw["schema"] != "stellar-forge.kafka-message.v1":
        raise InputError("Choose an original native Kafka message")
    for key in ("clusterId", "topicId", "topic"):
        label(raw[key], 300)
    integer(raw["partition"], 0, 2147483647, "Partition")
    offset(raw["offset"])
    if raw["timestampType"] not in {"NOT_AVAILABLE", "CREATE_TIME", "LOG_APPEND_TIME"}:
        raise InputError("Unknown native Kafka timestamp type")
    stamp = raw["timestampMs"]
    if raw["timestampType"] == "NOT_AVAILABLE":
        if stamp is not None:
            raise InputError("An unavailable native timestamp must remain null")
    elif not isinstance(stamp, str) or not re.fullmatch(r"-?(0|[1-9][0-9]{0,18})", stamp) or not -9223372036854775808 <= int(stamp) <= 9223372036854775807:
        raise InputError("Retain the exact native Kafka timestamp as a decimal string")
    if raw["leaderEpoch"] is not None:
        integer(raw["leaderEpoch"], 0, 2147483647, "Leader epoch")
    total = 0
    for key in ("keyBase64", "valueBase64"):
        decoded = unb64(raw[key])
        total += len(decoded) if decoded is not None else 0
    headers = raw["headers"]
    if not isinstance(headers, list) or len(headers) > 65536:
        raise InputError("Retain the ordered native Kafka headers within the message limit")
    for header in headers:
        exact(header, {"name", "valueBase64"})
        if not isinstance(header["name"], str) or len(header["name"]) > 65536:
            raise InputError("Kafka header names must retain their original text")
        try:
            total += len(header["name"].encode("utf-8"))
        except UnicodeError as error:
            raise InputError("Kafka header names must contain valid Unicode") from error
        decoded = unb64(header["valueBase64"])
        total += len(decoded) if decoded is not None else 0
    if total > 16 * 1024 * 1024:
        raise InputError("Native Kafka message exceeds 16 MiB")
    body = json_bytes(raw)
    return {"id": wire_identity(raw), "sha256": digest(body), "bytes": len(body), "payloadBytes": total, "wire": raw}


def decoded(raw, mode="json"):
    """Keep numbers in the original NDJSON JsonNumber representation."""
    record = wire(raw)
    key = unb64(raw["keyBase64"])
    value = unb64(raw["valueBase64"])
    key_text = None
    if key is not None:
        try:
            key_text = key.decode("utf-8")
        except UnicodeError:
            pass
    parsed, error = None, None
    state = "tombstone" if value is None else "binary"
    if value is not None and mode == "json":
        try:
            parsed = json.loads(value, parse_int=ndjson_source.JsonNumber,
                                parse_float=ndjson_source.JsonNumber,
                                parse_constant=ndjson_source._constant,
                                object_pairs_hook=ndjson_source._pairs)
            ndjson_source._validate_tree(parsed)
            state = "json"
        except (ValueError, UnicodeError, RecursionError, InputError) as issue:
            error = str(issue)[:240]
            state = "invalid-json"
    operations = [unb64(h["valueBase64"]) for h in raw["headers"] if h["name"] == "dbz.op"]
    gs = operations[0].decode("ascii") if len(operations) == 1 and operations[0] in {b"c", b"u", b"d"} else None
    partition_key = None if key is None else digest(json_bytes({
        "clusterId": raw["clusterId"], "topicId": raw["topicId"],
        "partition": raw["partition"], "keyBase64": raw["keyBase64"]}))
    envelope = {"eventId": record["id"], "partitionKeyId": partition_key,
        **{k: raw[k] for k in ("clusterId", "topicId", "topic", "offset", "timestampType",
                              "timestampMs", "keyBase64", "valueBase64", "headers")},
        "partition": str(raw["partition"]), "offsetOrder": raw["offset"].zfill(19),
        "leaderEpoch": None if raw["leaderEpoch"] is None else str(raw["leaderEpoch"]),
        "keyUtf8": key_text, "value": parsed, "valueState": state, "parseError": error,
        "goldskyOperation": gs, "deleted": value is None or gs == "d"}
    return record | {"envelope": envelope}


def api_message(raw):
    value = decoded(raw)
    envelope = value["envelope"]
    return {"id": value["id"], "sha256": value["sha256"],
        **{k: v for k, v in raw.items() if k != "schema"},
        **{k: envelope[k] for k in ("keyUtf8", "value", "valueState", "parseError", "goldskyOperation", "deleted")},
        "valueJson": ndjson_source.exact_json(envelope["value"]) if envelope["valueState"] == "json" else None}



def api_message_summary(raw, checksum, retained_bytes, goldsky_operation):
    """List validated retained wire metadata without decoding every message value."""
    key = unb64(raw["keyBase64"])
    state, preview, truncated = "null", None, False
    if key is not None:
        if not key:
            state, preview = "empty", ""
        else:
            try:
                text = key.decode("utf-8")
                state, preview, truncated = "utf8", text[:256], len(text) > 256
            except UnicodeError:
                state = "binary"
    encoded = raw["valueBase64"]
    value_bytes = None if encoded is None else len(encoded) // 4 * 3 - (2 if encoded.endswith("==") else 1 if encoded.endswith("=") else 0)
    return {"id": wire_identity(raw), "sha256": ident(checksum),
        **{key: raw[key] for key in ("clusterId", "topicId", "topic", "partition", "offset",
                                    "timestampType", "timestampMs", "leaderEpoch")},
        "keyState": state, "keyUtf8Preview": preview, "keyPreviewTruncated": truncated,
        "keyBytes": None if key is None else len(key), "valueBytes": value_bytes,
        "headerCount": len(raw["headers"]), "wireBytes": retained_bytes,
        "valueState": "tombstone" if encoded is None else "present",
        "goldskyOperation": goldsky_operation,
        "deleted": encoded is None or goldsky_operation == "d"}


def exact_document(value):
    """Emit original numeric lexemes while retaining ordinary API metadata numbers."""
    if isinstance(value, ndjson_source.JsonNumber) or value is None or type(value) is bool or isinstance(value, str):
        return value
    if type(value) in {int, float}:
        return ndjson_source.JsonNumber(json.dumps(value, allow_nan=False))
    if isinstance(value, (list, tuple)):
        return [exact_document(item) for item in value]
    if isinstance(value, dict):
        return {key: exact_document(item) for key, item in value.items()}
    raise InputError("Expected an original JSON response")


def api_bytes(value):
    return (ndjson_source.exact_json(exact_document(value)) + "\n").encode("utf-8")


def default_plan(name):
    fields = ["eventId", "partitionKeyId", "topic", "partition", "offset", "offsetOrder",
              "timestampType", "timestampMs", "keyUtf8", "valueState", "goldskyOperation"]
    nullable = {"partitionKeyId", "timestampMs", "keyUtf8", "goldskyOperation"}
    columns = [{"name": field, "path": [field], "type": "string",
                "nullable": field in nullable, "mode": "scalar", "missing": "error"}
               for field in fields]
    columns.extend([
        {"name": "keyState", "path": ["keyUtf8"], "type": "string", "mode": "state"},
        {"name": "valueJson", "path": ["value"], "type": "string", "mode": "json"},
        {"name": "deleted", "path": ["deleted"], "type": "boolean"},
    ])
    raw = {"schema": ndjson_source.SCHEMA, "name": label(name, 128), "recordPath": [],
        "columns": columns, "keys": ["eventId"],
        "filters": ["topic", "partition", "valueState", "goldskyOperation"],
        "sorts": ["offsetOrder"], "ranges": [], "defaultLimit": 50, "maxLimit": 1000,
        "maxBytes": MAX_SOURCE, "maxRows": 1000000, "maxCellChars": 1048576, "allowEmpty": True}
    return ndjson_source.validate_plan(raw)

"""MIT. Kafka controls and the maintained original NDJSON console on one private server."""
from __future__ import annotations
import os
from pathlib import Path
import shutil
from urllib.parse import urlsplit, parse_qs

from shared import HERE, SOURCE, RetainedHandler, RetainedServer, InputError, load_json
from contract import MAX_SOURCE, api_bytes, exact

MAX_PACKET = 6 * MAX_SOURCE + 32 * 1024 * 1024


def browser_assets():
    """Consume the same reviewed asset manifest used by the original packager."""
    manifest = load_json((HERE / "browser-assets.json").read_bytes())
    exact(manifest, {"schema", "root", "routes"})
    if manifest["schema"] != "stellar-forge.browser-assets.v1" or manifest["root"] != "./":
        raise InputError("Choose the original Kafka browser asset manifest")
    expected = {
        "/": ("public/index.html", "text/html; charset=utf-8"),
        "/app.js": ("public/app.js", "text/javascript; charset=utf-8"),
        "/style.css": ("public/style.css", "text/css; charset=utf-8"),
        "/ndjson-app.js": ("../ndjson/public/app.js", "text/javascript; charset=utf-8"),
        "/ndjson-style.css": ("../ndjson/public/style.css", "text/css; charset=utf-8"),
    }
    values = manifest["routes"]
    if not isinstance(values, list) or len(values) != len(expected):
        raise InputError("The Kafka console requires its complete five-route original asset map")
    result = {}
    for item in values:
        if not isinstance(item, list) or len(item) != 2 or not isinstance(item[0], str) or not isinstance(item[1], list) or len(item[1]) != 2:
            raise InputError("Invalid original Kafka browser route")
        route, asset = item
        if route in result or route not in expected or tuple(asset) != expected[route]:
            raise InputError("Kafka browser routes must match the original shared module and stylesheet")
        path = (HERE / asset[0]).resolve(strict=True)
        if not path.is_relative_to(SOURCE) or not path.is_file():
            raise InputError("The original Kafka browser asset is outside its source package")
        result[route] = (path, asset[1])
    return result


class Handler(RetainedHandler):
    server_version = "SF30-Kafka"

    def _json(self, value, status=200):
        data = api_bytes(value)
        self._headers(status, "application/json; charset=utf-8", len(data))
        self.wfile.write(data)

    def _query(self, target):
        parsed = parse_qs(target.query, keep_blank_values=True)
        if any(len(items) != 1 for items in parsed.values()):
            raise InputError("Repeated query parameters are not accepted")
        return {key: items[0] for key, items in parsed.items()}

    def _get(self):
        target = urlsplit(self.path)
        if target.path in self.server.browser_assets:
            self._gate(api=False)
            path, media = self.server.browser_assets[target.path]
            data = path.read_bytes()
            self._headers(200, media, len(data))
            self.wfile.write(data)
            return
        if not target.path.startswith("/api/kafka/"):
            return super()._get()
        self._gate()
        query = self._query(target)
        ws = self.server.workspace
        single = {
            "/api/kafka/connection": ws.connection,
            "/api/kafka/inspection": ws.inspection,
            "/api/kafka/capture": ws.capture,
            "/api/kafka/projection": ws.projection,
            "/api/kafka/message": ws.message,
        }
        if target.path in single:
            exact(query, {"id"})
            self._json(single[target.path](query["id"]))
        elif target.path == "/api/kafka/messages":
            exact(query, {"capture"}, {"offset", "limit"})
            self._json(ws.messages(query["capture"], int(query.get("offset", "0")), int(query.get("limit", "50"))))
        elif target.path == "/api/kafka/export":
            exact(query, {"build"}, {"projection"})
            with ws.mutex, ws.scratch() as temporary:
                archive = temporary / "kafka-project.zip"
                ws.export_kafka(query["build"], archive, query.get("projection"))
                self._download(archive, archive.name, "application/zip")
        else:
            self._json({"error": "Unknown local Kafka route"}, 404)

    def _post(self):
        target = urlsplit(self.path)
        if not target.path.startswith("/api/kafka/"):
            return super()._post()
        self._gate()
        if target.query:
            raise InputError("Kafka write routes do not accept query parameters")
        ws = self.server.workspace
        if target.path == "/api/kafka/import":
            with ws.mutex, ws.scratch() as temporary:
                archive = temporary / "customer-kafka.zip"
                with archive.open("xb") as output:
                    archive.chmod(0o600)
